    if n < 24: return bytes([n])
    raise SystemExit('too big')

def cbor_int(n):
    return bytes([n])

def text(s):
    b=s.encode(); return bytes([0x60+len(b)])+b

def arr(items):
    return bytes([0x80+len(items)])+b''.join(items)

