from pathlib import Path
# Build a coSWID-like root map with tags as small ints guessed from source names:
# root includes FILES/PAYLOAD? We'll try a direct file payload nesting.
# Need a hash field whose value is not an array; parser path checks cbor_isa_array(pairs[i].value) and then cbor_array_get.

def u(n):
    assert 0 <= n < 24
    return bytes([n])
def t(s):
    b=s.encode(); assert len(b)<24
    return bytes([0x60+len(b)])+b
def a(items):
    return bytes([0x80+len(items)])+b''.join(items)
def m(pairs):
    return bytes([0xa0+len(pairs)])+b''.join(k+v for k,v in pairs)
# Try tags: 0=tag id, 1=software name, 2=version, 3=meta, 5=file, 6=directory, 8=hash, 9=fs name, 10=size.
# We only need parser to reach file/hash logic, so include root map with file entry.
# file map: fs name text, size uint, hash scalar text (non-array)
file_map = m([
    (u(9), t('f')),
    (u(10), u(1)),
    (u(8), t('X')),
])
root = m([
    (u(5), file_map),
])
Path('/tmp/cand2.bin').write_bytes(root)
print(root.hex())
